218	// AddOption applies options to an addition measurement. See
219	// [MeasurementOption] for other options that can be used as an AddOption.
220	type AddOption interface {
221		applyAdd(AddConfig) AddConfig
222	}
223	
224	// AddConfig contains options for an addition measurement.
225	type AddConfig struct {
226		attrs attribute.Set
227	}
228	
229	// NewAddConfig returns a new [AddConfig] with all opts applied.
230	func NewAddConfig(opts []AddOption) AddConfig {
231		config := AddConfig{attrs: *attribute.EmptySet()}
232		for _, o := range opts {
233			if _, ok := o.(experimentalOption); ok {
234				continue
235			}
236			config = o.applyAdd(config)
237		}
238		return config
239	}
240	
241	// Attributes returns the configured attribute set.
242	func (c AddConfig) Attributes() attribute.Set {
243		return c.attrs
244	}
