4	package metric // import "go.opentelemetry.io/otel/metric"
5	
6	import (
7		"slices"
8	
9		"go.opentelemetry.io/otel/attribute"
10	)
11	
12	// MeterConfig contains options for Meters.
13	type MeterConfig struct {
14		instrumentationVersion string
15		schemaURL              string
16		attrs                  attribute.Set
17	
18		// Ensure forward compatibility by explicitly making this not comparable.
19		noCmp [0]func() //nolint: unused  // This is indeed used.
20	}
21	
22	// InstrumentationVersion returns the version of the library providing
23	// instrumentation.
24	func (cfg MeterConfig) InstrumentationVersion() string {
25		return cfg.instrumentationVersion
26	}
27	
28	// InstrumentationAttributes returns the attributes associated with the library
29	// providing instrumentation.
30	func (cfg MeterConfig) InstrumentationAttributes() attribute.Set {
31		return cfg.attrs
32	}
33	
34	// SchemaURL is the schema_url of the library providing instrumentation.
35	func (cfg MeterConfig) SchemaURL() string {
36		return cfg.schemaURL
37	}
38	
39	// MeterOption is an interface for applying Meter options.
40	type MeterOption interface {
41		// applyMeter is used to set a MeterOption value of a MeterConfig.
42		applyMeter(MeterConfig) MeterConfig
43	}
44	
45	type experimentalOption interface {
46		Experimental()
47	}
48	
49	// NewMeterConfig creates a new MeterConfig and applies
50	// all the given options.
51	func NewMeterConfig(opts ...MeterOption) MeterConfig {
52		var config MeterConfig
53		for _, o := range opts {
54			if _, ok := o.(experimentalOption); ok {
55				continue
56			}
57			config = o.applyMeter(config)
58		}
59		return config
60	}
61	
62	type meterOptionFunc func(MeterConfig) MeterConfig
63	
64	func (fn meterOptionFunc) applyMeter(cfg MeterConfig) MeterConfig {
65		return fn(cfg)
66	}
67	
68	// WithInstrumentationVersion sets the instrumentation version.
69	func WithInstrumentationVersion(version string) MeterOption {
70		return meterOptionFunc(func(config MeterConfig) MeterConfig {
71			config.instrumentationVersion = version
72			return config
73		})
74	}
75	
76	// WithInstrumentationAttributes adds the instrumentation attributes.
77	//
78	// This is equivalent to calling [WithInstrumentationAttributeSet] with an
79	// [attribute.Set] created from a clone of the passed attributes.
80	// [WithInstrumentationAttributeSet] is recommended for more control.
81	//
82	// If multiple [WithInstrumentationAttributes] or [WithInstrumentationAttributeSet]
83	// options are passed, the attributes will be merged together in the order
84	// they are passed. Attributes with duplicate keys will use the last value passed.
85	func WithInstrumentationAttributes(attr ...attribute.KeyValue) MeterOption {
86		set := attribute.NewSet(slices.Clone(attr)...)
87		return WithInstrumentationAttributeSet(set)
88	}
89	
90	// WithInstrumentationAttributeSet adds the instrumentation attributes.
91	//
92	// If multiple [WithInstrumentationAttributes] or [WithInstrumentationAttributeSet]
93	// options are passed, the attributes will be merged together in the order
94	// they are passed. Attributes with duplicate keys will use the last value passed.
95	func WithInstrumentationAttributeSet(set attribute.Set) MeterOption {
96		if set.Len() == 0 {
97			return meterOptionFunc(func(config MeterConfig) MeterConfig {
98				return config
99			})
100		}
101	
102		return meterOptionFunc(func(config MeterConfig) MeterConfig {
103			if config.attrs.Len() == 0 {
104				config.attrs = set
105			} else {
106				config.attrs = mergeSets(config.attrs, set)
107			}
108			return config
109		})
110	}
111	
112	// WithSchemaURL sets the schema URL.
113	func WithSchemaURL(schemaURL string) MeterOption {
114		return meterOptionFunc(func(config MeterConfig) MeterConfig {
115			config.schemaURL = schemaURL
116			return config
117		})
118	}
