// WithDefaultAttributes returns a [metric.InstrumentOption] that specifies the
// attribute keys that are allowed by default for the metric instrument being
// created.
//
// When the returned option is passed during the creation of an instrument,
// only the attributes whose keys are contained in keys are included in the
// data points recorded for that instrument. Any attribute whose key is not in
// keys is dropped.
//
// Passing no keys results in all attributes being filtered out, producing data
// points with an empty attribute set.
//
// When this option is not provided, no filtering occurs and all recorded
// attributes are retained.
//
// This filtering is overridden when a view explicitly matches the instrument.
// In that case, the view's attribute configuration takes precedence.
func WithDefaultAttributes(keys ...attribute.Key) metric.InstrumentOption {
	// Ensure a non-nil slice is stored even when no keys are provided so the
	// SDK can distinguish "filter everything" (option provided with no keys)
	// from "do not filter" (option not provided at all).
	if keys == nil {
		keys = []attribute.Key{}
	}
	return defaultAttributesOption{keys: keys}
}

// defaultAttributesOption is a [metric.InstrumentOption] that carries the set
// of attribute keys allowed by default for an instrument.
type defaultAttributesOption struct {
	keys []attribute.Key
}

// Experimental marks the option as experimental. It also ensures the standard
// metric API drops this option instead of applying it, preventing panics when
// the option is used with an API implementation that is unaware of it.
func (defaultAttributesOption) Experimental() {}

// AllowedKeys returns the attribute keys allowed by default. A nil return
// value signals that no filtering should occur; a non-nil (possibly empty)
// slice signals that only the returned keys are allowed.
func (o defaultAttributesOption) AllowedKeys() []attribute.Key { return o.keys }

